public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (start == null || end == null || start.length != n || end.length != n) {
        throw new IllegalArgumentException("start and end must be non-null arrays of length n");
    }
    if (paths == null) {
        throw new IllegalArgumentException("paths cannot be null");
    }

    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            throw new IllegalArgumentException("Each path must be an array of length 2*n");
        }
        int[] coord1 = new int[n];
        int[] coord2 = new int[n];
        System.arraycopy(path, 0, coord1, 0, n);
        System.arraycopy(path, n, coord2, 0, n);
        String key1 = coordToKey.apply(coord1);
        String key2 = coordToKey.apply(coord2);
        graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start or end not in graph, cannot travel unless they are the same (handled above)
    if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
