public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k == 0) {
        return false; // division by zero is undefined
    }

    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : arr) {
        int r = ((num % k) + k) % k; // ensure non-negative remainder
        freq.put(r, freq.getOrDefault(r, 0) + 1);
    }

    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int r = entry.getKey();
        int count = entry.getValue();

        // Remainder 0 must have even count
        if (r == 0) {
            if (count % 2 != 0) {
                return false;
            }
            continue;
        }

        // If k is even, remainder k/2 must have even count
        if (k % 2 == 0 && r == k / 2) {
            if (count % 2 != 0) {
                return false;
            }
            continue;
        }

        int complement = (k - r) % k;
        // Skip if complement has already been processed
        if (r > complement) {
            continue;
        }

        int countComp = freq.getOrDefault(complement, 0);
        if (count != countComp) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Validate inputs
    if (n <= 0) {
        throw new IllegalArgumentException("Number of nodes must be positive.");
    }
    if (edges == null || edges.length != n - 1) {
        throw new IllegalArgumentException("Edges array must contain exactly n-1 edges.");
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must equal n.");
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two node indices.");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds.");
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    // DFS to compute time
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int child : graph[node]) {
        if (child == parent) {
            continue;
        }
        int childTime = dfs(child, node, graph, hasApple);
        if (childTime > 0 || hasApple[child]) {
            time += childTime + 2; // go to child and back
        }
    }
    return time;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    // Assuming the string contains only lowercase English letters.
    int[] freq = new int[26];
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c < 'a' || c > 'z') {
            // If the string contains characters outside 'a'-'z',
            // fall back to a more general approach using a TreeMap.
            return sortStringGeneral(s);
        }
        freq[c - 'a']++;
    }

    StringBuilder sb = new StringBuilder(n);
    while (sb.length() < n) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return sb.toString();
}

/**
 * Fallback method that works for any characters by using a TreeMap.
 */
private String sortStringGeneral(String s) {
    java.util.TreeMap<Character, Integer> freqMap = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freqMap.put(c, freqMap.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (sb.length() < s.length()) {
        // Ascending pass
        java.util.NavigableSet<Character> ascKeys = freqMap.navigableKeySet();
        for (Character c : ascKeys) {
            int count = freqMap.get(c);
            if (count > 0) {
                sb.append(c);
                if (count == 1) {
                    freqMap.remove(c);
                } else {
                    freqMap.put(c, count - 1);
                }
            }
        }
        // Descending pass
        java.util.NavigableSet<Character> descKeys = freqMap.descendingKeySet();
        for (Character c : descKeys) {
            int count = freqMap.get(c);
            if (count > 0) {
                sb.append(c);
                if (count == 1) {
                    freqMap.remove(c);
                } else {
                    freqMap.put(c, count - 1);
                }
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        // iterate k in reverse to avoid using updated values in the same iteration
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1] == null) continue;
            if (dp[k] == null) dp[k] = new HashSet<>();
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long targetLong = (totalSum * k) / n;
        if (targetLong < Integer.MIN_VALUE || targetLong > Integer.MAX_VALUE) {
            continue;
        }
        int target = (int) targetLong;
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

