public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (k > n) {
        return false;
    }
    // Limit k to avoid excessive memory usage (2^k must fit in int array)
    if (k > 20) { // 2^20 = 1,048,576, reasonable upper bound
        return false;
    }
    int total = 1 << k; // total number of binary strings of length k
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1; // mask to keep only k bits
    int value = 0;
    // Build initial value for the first k characters
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    if (!seen[value]) {
        seen[value] = true;
        count++;
        if (count == total) {
            return true;
        }
    }
    // Slide the window over the string
    for (int i = k; i < n; i++) {
        value = ((value << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
    // Handle null inputs
    if (sentence == null || searchWord == null) {
        return -1;
    }

    // Trim the sentence to avoid leading/trailing spaces affecting split
    String trimmed = sentence.trim();
    if (trimmed.isEmpty()) {
        return -1;
    }

    // Split by one or more whitespace characters
    String[] words = trimmed.split("\\s+");
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        if (word.startsWith(searchWord)) {
            // Return 1-based index
            return i + 1;
        }
    }
    return -1;
}

public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                insertions++;   // insert a '(' before this ')'
                balance++;      // account for the inserted '('
            }
            balance--;          // consume the current ')'
        } else {
            throw new IllegalArgumentException("Invalid character in input: " + c);
        }
    }
    insertions += balance; // insert ')' for remaining unmatched '('
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        return 0;
    }
    int start = (n + 1) / 2;          // first index with surplus
    int count = n - start;            // number of surplus elements
    long ops = (long) start * count;  // use long to avoid overflow
    return (int) ops;
}

