public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxEnding = nums[0];
    long maxSoFar = nums[0];
    long minEnding = nums[0];
    long minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    long result = Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    // Greedy: pick largest Fibonacci numbers first
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> divisors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            divisors.add(i);
            int other = n / i;
            if (other != i) {
                divisors.add(other);
            }
        }
    }
    java.util.Collections.sort(divisors);
    if (k - 1 < divisors.size()) {
        return divisors.get(k - 1);
    } else {
        return -1;
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // In ASCII, the difference between a lowercase and its uppercase counterpart is 32
            if (Math.abs(top - c) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    java.util.Set<String> used = new java.util.HashSet<>();
    int[] max = new int[1];
    dfs(s, 0, used, max);
    return max[0];
}

private void dfs(String s, int index, java.util.Set<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int len = 1; index + len <= s.length(); len++) {
        String sub = s.substring(index, index + len);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, index + len, used, max);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in the current folder, no change
        } else {
            // any other string is treated as a folder entry
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k is out of valid range for given n");
    }
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        int remaining = n - i - 1;
        for (int val = 1; val <= 26; val++) {
            int minRemaining = remaining * 1;
            int maxRemaining = remaining * 26;
            int remainingSum = k - val;
            if (remainingSum >= minRemaining && remainingSum <= maxRemaining) {
                sb.append((char) ('a' + val - 1));
                k -= val;
                break;
            }
        }
    }
    return sb.toString();
}

