public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitCount++;
            }
        }
        if ((bitCount % 3) == 1) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    // Start BFS from digits 1 to 9
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    // Digital root formula: 0 -> 0, otherwise 1 + (num-1) % 9
    return num == 0 ? 0 : 1 + (num - 1) % 9;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    if (mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int n = mat[0].length;

    // Validate that all rows have the same length
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j + 1 < n ? anti[i - 1][j + 1] : 0) + 1;

                int localMax = Math.max(
                        Math.max(horiz[i][j], vert[i][j]),
                        Math.max(diag[i][j], anti[i][j])
                );
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                horiz[i][j] = vert[i][j] = diag[i][j] = anti[i][j] = 0;
            }
        }
    }

    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero directly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Use long to avoid overflow when n == Integer.MIN_VALUE
    long absValue = negative ? -(long) n : (long) n;
    String absStr = Long.toString(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = absStr.length() - 1; i >= 0; i--) {
        sb.append(absStr.charAt(i));
        count++;
        if (count % 3 == 0 && i > 0) {
            sb.append('.');
        }
    }
    sb.reverse();

    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    backtrack(A, used, 0, -1, isSquare, count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int depth, int last,
                              boolean[] isSquare, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) {
            continue; // skip duplicate values to avoid counting same permutation
        }
        if (last != -1 && !isSquare[A[last] + A[i]]) {
            continue; // sum with previous element is not a perfect square
        }
        used[i] = true;
        backtrack(A, used, depth + 1, i, isSquare, count);
        used[i] = false;
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            // even sum: traverse from endRow to startRow
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            // odd sum: traverse from startRow to endRow
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    result = buildStrobogrammatic(n, n);
    return result;
}

private static java.util.List<String> buildStrobogrammatic(int current, int original) {
    java.util.List<String> list = new java.util.ArrayList<>();
    if (current == 0) {
        list.add("");
        return list;
    }
    if (current == 1) {
        list.add("0");
        list.add("1");
        list.add("8");
        return list;
    }
    java.util.List<String> inner = buildStrobogrammatic(current - 2, original);
    for (String s : inner) {
        if (current != original) {
            list.add("0" + s + "0");
        }
        list.add("1" + s + "1");
        list.add("6" + s + "9");
        list.add("8" + s + "8");
        list.add("9" + s + "6");
    }
    return list;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) {
        return false;
    }
    if (points[0][0] == points[2][0] && points[0][1] == points[2][1]) {
        return false;
    }
    if (points[1][0] == points[2][0] && points[1][1] == points[2][1]) {
        return false;
    }
    long x1 = (long) points[1][0] - points[0][0];
    long y1 = (long) points[1][1] - points[0][1];
    long x2 = (long) points[2][0] - points[0][0];
    long y2 = (long) points[2][1] - points[0][1];
    long cross = x1 * y2 - y1 * x2;
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    while (result.size() < n) {
        result.add(cur);
        if (cur == n) {
            break;
        }
        if (cur <= n / 10) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    try {
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return sum;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return 0
        return 0;
    }
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize dp array with a large value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
